 for(const row of inputs)if(sourceHash(readFileSync(row.path,'utf8'))!==row.sourceHash)throw Error('Changed input '+row.path);
 writeFileSync('.git/q100-atomic-sync.json',JSON.stringify({command,exit:child.exitCode,output,sourceInputs:inputs,source:readFileSync('.git/q100-atomic-sync.ts','utf8')},null,2)+'\n');
 console.log(output.slice(-180));if(child.exitCode!==0)throw Error('Sync compatibility failed');
}finally{storage.cleanup();}
